package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class SaveClaim {
    public void save(@Val Claim claim, ClaimRepository repository, Out<Claim> saved) {
        saved.set(repository.save(claim));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

/**
 * Stores the batch a settle puts the claim in: a settle (or re-settle) that is part of a bulk settle (the body's batch
 * token) gives it that bulk settle's batch number — the sheet's next the first time — whether it ends SETTLED or
 * PENDING; one taken one at a time gives it none. A reject (back to OPEN) clears it; other changes keep it.
 */
public class SaveClaimBatch {
    public void save(@Val ClaimAction action, @Val Claim claim, @Val ClaimActionRequest request,
            SettleBatchRepository batches) {
        switch (action) {
            case SETTLE, PEND, RESETTLE -> batches.saveBatch(claim.sheetId(), claim.id(),
                    request.batch().isEmpty() ? null : batches.numberFor(claim.sheetId(), request.batch()));
            case REJECT -> batches.saveBatch(claim.sheetId(), claim.id(), null);
            default -> {
            }
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

/** Stores the reason a void was given with (none: nothing stored); other status changes store nothing. */
public class SaveClaimVoidReason {
    public void save(@Val ClaimAction action, @Val Claim claim, @Val ClaimActionRequest request,
            ClaimRepository repository) {
        if (action == ClaimAction.VOID && !request.reason().isEmpty()) {
            repository.saveVoidReason(claim, request.reason());
        }
    }
}
package net.officefloor.hq.app.watch;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimNumber;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Follows a claim's own record, when the claim was just settled, approved or re-settled (it ends SETTLED), with one
 * NOTIFY line per user watching its person, in the order they started watching. A clerk's settle that went PENDING
 * notifies no one.
 */
public class NotifyWatchers {
    public void audit(@Val Claim claim, @Val ClaimNumber number, PersonRepository people, WatchRepository watches,
            @RequestParam("user") String user, Audit audit) {
        if (claim.status() != ClaimStatus.SETTLED) {
            return;
        }
        Person person = people.find(claim.sheetId(), claim.personId());
        String name = person == null ? "" : person.name();
        for (String watcher : watches.watchers(claim.sheetId(), claim.personId())) {
            audit.record("NOTIFY sheet=" + claim.sheetId() + " by=" + user + " user=" + watcher + " person=" + name
                    + Claim.auditNumber(number.value()));
        }
    }
}
